-- A Plus B
INSERT INTO problems (slug, title, description, constraints, difficulty, time_limit_ms, memory_limit_mb, published) VALUES ($q$a-plus-b$q$, $q$A Plus B$q$, $q$Given two integers `a` and `b`, print their sum.

This is the classic first problem: read the input from standard input and write the answer to standard output.

### Input
A single line containing two space-separated integers `a` and `b`.

### Output
Print one integer: `a + b`.$q$, $q$- `-10^9 <= a, b <= 10^9`
- The sum may not fit in a 32-bit integer; use a 64-bit type (`long long` in C++).$q$, $q$EASY$q$, 1000, 256, TRUE) ON CONFLICT DO NOTHING;
INSERT INTO problem_tags (problem_id, tag_id) SELECT p.id, t.id FROM problems p, tags t WHERE p.slug = $q$a-plus-b$q$ AND lower(t.name) = lower($q$math$q$) ON CONFLICT DO NOTHING;
INSERT INTO problem_tags (problem_id, tag_id) SELECT p.id, t.id FROM problems p, tags t WHERE p.slug = $q$a-plus-b$q$ AND lower(t.name) = lower($q$implementation$q$) ON CONFLICT DO NOTHING;
INSERT INTO test_cases (problem_id, position, input, expected_output, explanation, is_sample, points) SELECT id, 1, $q$3 5$q$, $q$8$q$, $q$3 + 5 = 8.$q$, TRUE, 0 FROM problems WHERE slug = $q$a-plus-b$q$;
