-- Reverse the Words
INSERT INTO problems (slug, title, description, constraints, difficulty, time_limit_ms, memory_limit_mb, published) VALUES ($q$reverse-words$q$, $q$Reverse the Words$q$, $q$You are given a sentence made of words separated by **single spaces**. Print the same words in reverse order, still separated by single spaces.

The letters inside each word keep their original order.

### Input
One line containing the sentence.

### Output
One line containing the words in reverse order.$q$, $q$- The sentence has between 1 and 10^5 characters.
- Words consist of lowercase English letters.
- There are no leading, trailing, or repeated spaces.$q$, $q$EASY$q$, 1000, 256, TRUE) ON CONFLICT DO NOTHING;
INSERT INTO problem_tags (problem_id, tag_id) SELECT p.id, t.id FROM problems p, tags t WHERE p.slug = $q$reverse-words$q$ AND lower(t.name) = lower($q$strings$q$) ON CONFLICT DO NOTHING;
INSERT INTO problem_tags (problem_id, tag_id) SELECT p.id, t.id FROM problems p, tags t WHERE p.slug = $q$reverse-words$q$ AND lower(t.name) = lower($q$implementation$q$) ON CONFLICT DO NOTHING;
