-- Valid Palindrome
INSERT INTO problems (slug, title, description, constraints, difficulty, time_limit_ms, memory_limit_mb, published) VALUES ($q$valid-palindrome$q$, $q$Valid Palindrome$q$, $q$A phrase is a **palindrome** if, after removing every character that is not a letter or digit and ignoring letter case, it reads the same forwards and backwards.

Given a line of text, decide whether it is a palindrome. An empty phrase (nothing left after filtering) counts as a palindrome.

### Input
A single line of text (it may contain spaces and punctuation).

### Output
Print `YES` if the phrase is a palindrome, otherwise `NO`.$q$, $q$- The line contains between 1 and 2 * 10^5 printable ASCII characters.$q$, $q$EASY$q$, 1000, 256, TRUE) ON CONFLICT DO NOTHING;
INSERT INTO problem_tags (problem_id, tag_id) SELECT p.id, t.id FROM problems p, tags t WHERE p.slug = $q$valid-palindrome$q$ AND lower(t.name) = lower($q$strings$q$) ON CONFLICT DO NOTHING;
INSERT INTO problem_tags (problem_id, tag_id) SELECT p.id, t.id FROM problems p, tags t WHERE p.slug = $q$valid-palindrome$q$ AND lower(t.name) = lower($q$two-pointers$q$) ON CONFLICT DO NOTHING;
