-- Balanced Brackets
INSERT INTO problems (slug, title, description, constraints, difficulty, time_limit_ms, memory_limit_mb, published) VALUES ($q$balanced-brackets$q$, $q$Balanced Brackets$q$, $q$A string made only of the characters `(`, `)`, `[`, `]`, `{` and `}` is **balanced** if every opening bracket is closed by a bracket of the same type, and brackets are closed in the correct order.

### Input
A single line containing the bracket string.

### Output
Print `YES` if the string is balanced, otherwise `NO`.$q$, $q$- The string length is between 1 and 10^5.
- Only the six bracket characters appear.$q$, $q$EASY$q$, 1000, 256, TRUE) ON CONFLICT DO NOTHING;
