-- Minimum Coins
INSERT INTO problems (slug, title, description, constraints, difficulty, time_limit_ms, memory_limit_mb, published) VALUES ($q$minimum-coins$q$, $q$Minimum Coins$q$, $q$You have an unlimited supply of coins in `n` different denominations. Find the **fewest coins** needed to make exactly `amount`, or report that it is impossible.

### Input
- The first line contains `n` and `amount`.
- The second line contains the `n` coin denominations.

### Output
Print the minimum number of coins, or `-1` if the amount cannot be formed.$q$, $q$- `1 <= n <= 12`
- `1 <= coin value <= 10^4`
- `1 <= amount <= 10^4`$q$, $q$MEDIUM$q$, 1500, 256, TRUE) ON CONFLICT DO NOTHING;
