-- Longest Increasing Subsequence
INSERT INTO problems (slug, title, description, constraints, difficulty, time_limit_ms, memory_limit_mb, published) VALUES ($q$longest-increasing-subsequence$q$, $q$Longest Increasing Subsequence$q$, $q$Given a sequence of `n` integers, find the length of its longest **strictly increasing subsequence**. A subsequence keeps the original order but may skip elements.

### Input
- The first line contains `n`.
- The second line contains `n` space-separated integers.

### Output
Print the length of the longest strictly increasing subsequence.$q$, $q$- `1 <= n <= 2 * 10^5`
- `-10^9 <= a[i] <= 10^9`
- An `O(n log n)` solution is expected.$q$, $q$MEDIUM$q$, 2000, 256, TRUE) ON CONFLICT DO NOTHING;
